// ─── File: src/main/java/com/bank/jvm/DeadlockDemo.java ───
package com.bank.jvm;

import java.math.BigDecimal;
import java.util.logging.*;

// Shows a deadlock forming, detecting it, then the ordered fix running cleanly.
public class DeadlockDemo {
    private static final Logger log = Logger.getLogger(DeadlockDemo.class.getName());

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        Logger root = Logger.getLogger("");
        for (Handler old : root.getHandlers()) root.removeHandler(old);
        root.addHandler(h);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", new BigDecimal("250000"));

        // Start the deadlock detector watching in the background.
        DeadlockDetector detector = new DeadlockDetector();
        detector.start();

        // NAIVE: two opposite transfers lock accounts in call order -> deadlock.
        NaiveTransferService naive = new NaiveTransferService();
        Thread t1 = new Thread(() -> naive.transfer(rajesh, priya, new BigDecimal("50000")), "txf-R-to-P");
        Thread t2 = new Thread(() -> naive.transfer(priya, rajesh, new BigDecimal("30000")), "txf-P-to-R");
        t1.start(); t2.start();

        Thread.sleep(3000);            // give the deadlock time to form + be detected
        detector.checkOnce();          // report any deadlock explicitly

        log.warning("Naive transfers are deadlocked (see detector). Now the SAFE version:");

        // SAFE: ordered locking prevents the circular wait entirely.
        Account a = new Account("SAV2001", new BigDecimal("1000000"));
        Account b = new Account("CUR3001", new BigDecimal("250000"));
        SafeTransferService safe = new SafeTransferService();
        Thread s1 = new Thread(() -> safe.transfer(a, b, new BigDecimal("50000")), "safe-A-to-B");
        Thread s2 = new Thread(() -> safe.transfer(b, a, new BigDecimal("30000")), "safe-B-to-A");
        s1.start(); s2.start(); s1.join(); s2.join();
        log.info("SAFE transfers both completed with no deadlock");
        detector.stop();
    }
}

