class Account {
    private final String accountId; private BigDecimal balance;
    Account(String id, BigDecimal bal) { accountId = id; balance = bal; }
    String getAccountId() { return accountId; }
    void debit(BigDecimal amt)  { balance = balance.subtract(amt); }
    void credit(BigDecimal amt) { balance = balance.add(amt); }
}

// ─── Would be in NaiveTransferService.java in a real project ───
class NaiveTransferService {
    private static final Logger log = Logger.getLogger(NaiveTransferService.class.getName());
    // BUG: locks 'from' then 'to' in call order -> opposite transfers deadlock.
    void transfer(Account from, Account to, BigDecimal amount) {
        synchronized (from) {
            log.info(Thread.currentThread().getName() + " locked " + from.getAccountId());
            try { Thread.sleep(200); } catch (InterruptedException ignored) {}
            synchronized (to) { // blocks forever if the other thread holds 'to'
                from.debit(amount); to.credit(amount);
            }
        }
    }
}

// ─── Would be in SafeTransferService.java in a real project ───
class SafeTransferService {
    private static final Logger log = Logger.getLogger(SafeTransferService.class.getName());
    // FIX: always lock the lower accountId first -> no circular wait possible.
    void transfer(Account from, Account to, BigDecimal amount) {
        Account first  = from.getAccountId().compareTo(to.getAccountId()) <= 0 ? from : to;
        Account second = (first == from) ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.debit(amount); to.credit(amount);
                log.info(Thread.currentThread().getName() + " completed "
                        + from.getAccountId() + "->" + to.getAccountId());
            }
        }
    }
}

