class DeadlockDetector {
    private static final Logger log = Logger.getLogger(DeadlockDetector.class.getName());
    private final java.lang.management.ThreadMXBean bean =
            java.lang.management.ManagementFactory.getThreadMXBean();
    private volatile boolean running = true;
    private Thread watcher;

    void start() {
        watcher = new Thread(() -> { while (running) { checkOnce(); sleep(1000); } }, "deadlock-detector");
        watcher.setDaemon(true); watcher.start();
    }
    // Core: ThreadMXBean finds any threads locked in a deadlock cycle.
    void checkOnce() {
        long[] ids = bean.findDeadlockedThreads();
        if (ids != null) {
            var infos = bean.getThreadInfo(ids, true, true);
            log.severe("DEADLOCK DETECTED among " + ids.length + " threads:");
            for (var info : infos) {
                log.severe("  '" + info.getThreadName() + "' BLOCKED waiting for "
                        + info.getLockName() + " held by '" + info.getLockOwnerName() + "'");
            }
        }
    }
    void stop() { running = false; }
    private void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException ignored) {} }
}
